import json
ddl=json.load(open('ddl.json')); inp=json.load(open('inputs.json')); pv=json.load(open('previews.json')); out=json.load(open('outputs.json'))
r7=json.load(open('/workspace/au7/run126.json'))
J=lambda x: "$J$"+json.dumps(x)+"$J$"
L=["drop schema if exists costing cascade; create schema costing;",
"drop table if exists public.production_batch_size_ref cascade;",
"create schema if not exists auth; create or replace function auth.uid() returns uuid language sql as $$ select null::uuid $$;",
"do $$ begin create role anon; exception when others then null; end $$; do $$ begin create role authenticated; exception when others then null; end $$;"]
for t in ddl:
    L.append(t['ddl'])
for t in ddl:
    if t['cons']:
        for c in t['cons'].split('\n'):
            if ' FOREIGN KEY ' in c: continue
            if t['n']=='cost_pool_monthly_snapshot' and ' CHECK ' in c: continue
            L.append(c)
L.append("""do $$ declare r record; begin for r in select c.table_schema, c.table_name from information_schema.columns c where c.table_schema in ('costing','public') and c.column_name='id' and c.column_default is null and c.is_identity='NO' and c.data_type in ('bigint','integer') loop execute format('alter table %I.%I alter column id add generated by default as identity (start with 50000000)', r.table_schema, r.table_name); end loop; end $$;""")
L.append("""create view costing.v_costing_run_effective_designation as select * from (values (119::bigint,'REFERENCE'::text),(122::bigint,'APPROVED'::text)) v(refresh_run_id,designation);""")
L.append("create function costing.fn_wp04_readiness_bump_source_epoch() returns trigger language plpgsql as $$ begin return null; end $$;")
for f in inp['policy_fns']: L.append(f.replace('\r','')+';')
L.append(open('live_sku_lineage.sql').read()+';')
# fixtures for stubs
L.append("create table costing.fx_foundation(refresh_run_id bigint primary key, j jsonb); create table costing.fx_dlprev(refresh_run_id bigint primary key, j jsonb);")
L.append("create table costing.fx_packresp(route_family_id bigint, rule_id bigint, responsibility_code text, resolution_source text, rationale text);")
L.append("create table costing.fx_ar(sku_id bigint primary key, raw_status text, effective_status text, acceptance_id bigint, evidence_fingerprint text);")
L.append("create table costing.demand_fixture(refresh_run_id bigint, product_id bigint, product_name text, product_base_uom text, commercial_base_qty numeric, internal_base_qty numeric, total_manufacturing_base_qty numeric, monthly_driver_status text, commercial_recipient_sku_count int, demand_source text, demand_note text, internal_evidence_json jsonb);")
L.append("""create function costing.fn_preview_shared_standard_batch_route_foundation(p_period_start date, p_valuation_date date, p_refresh_run_id bigint, p_route_family_id bigint) returns jsonb language sql stable as $$ select j from costing.fx_foundation where refresh_run_id=p_refresh_run_id $$;
create function costing.fn_preview_direct_labour_shadow_workload(p_policy_id bigint, p_period_start date, p_valuation_date date, p_refresh_run_id bigint, p_route_family_id bigint) returns jsonb language sql stable as $$ select j from costing.fx_dlprev where refresh_run_id=p_refresh_run_id $$;
create function costing.fn_resolve_packing_labour_responsibility(p_route_family_id bigint, p_valuation_date date) returns table(rule_id bigint, route_family_id bigint, responsibility_code text, resolution_source text, rationale text) language sql stable as $$ select x.rule_id, x.route_family_id, x.responsibility_code, x.resolution_source, x.rationale from costing.fx_packresp x where x.route_family_id is not distinct from p_route_family_id $$;
create function costing.fn_sales_allocation_quantity_driver_review_status(p_snapshot_id bigint) returns table(raw_status text, effective_status text, acceptance_id bigint, evidence_fingerprint text) language sql stable as $$ select a.raw_status,a.effective_status,a.acceptance_id,a.evidence_fingerprint from costing.sku_sales_allocation_basis_snapshot b join costing.fx_ar a on a.sku_id=b.sku_id where b.id=p_snapshot_id $$;
create function costing.fn_total_manufacturing_product_demand_as_of(p_period_start date, p_valuation_date date, p_refresh_run_id bigint)
returns table(product_id bigint, product_name text, product_base_uom text, commercial_base_qty numeric, internal_base_qty numeric, total_manufacturing_base_qty numeric, monthly_driver_status text, commercial_recipient_sku_count int, demand_source text, demand_note text, internal_evidence_json jsonb)
language sql stable as $$ select f.product_id, f.product_name, f.product_base_uom, f.commercial_base_qty, f.internal_base_qty, f.total_manufacturing_base_qty, f.monthly_driver_status, f.commercial_recipient_sku_count, f.demand_source, f.demand_note, f.internal_evidence_json from costing.demand_fixture f where f.refresh_run_id=p_refresh_run_id $$;""")
for tg in inp['triggers']: L.append(tg+';')
open('fx_ddl.sql','w').write('\n'.join(L))
# ---- data
D=[]
def pop(t,rows,schema='costing'):
    D.append(f"insert into {schema}.{t} select * from jsonb_populate_recordset(null::{schema}.{t}, {J(rows)}::jsonb);")
for t in ['costing_refresh_run','costing_refresh_run_stage','cost_pool_monthly_snapshot','direct_labour_component_pool_snapshot','batch_true_standard_switch',
          'production_overhead_workload_policy','production_overhead_scope_factor','production_overhead_behaviour_factor','production_overhead_resource_factor',
          'direct_labour_workload_policy','sales_allocation_default_policy','production_route_family']:
    pop(t,inp[t])
pop('production_batch_size_ref',inp['production_batch_size_ref'],'public')
pop('sku_sales_allocation_basis_snapshot',out['sku_sales_allocation_basis_snapshot'])
pop('product_qc_workload_snapshot',r7['qcw'])
D.append(f"insert into costing.fx_packresp select * from jsonb_populate_recordset(null::costing.fx_packresp, {J(inp['packresp'])}::jsonb);")
bid={b['id']:b['sku_id'] for b in out['sku_sales_allocation_basis_snapshot']}
ar=[dict(a['r'],sku_id=bid[a['id']]) for a in inp['arstatus']]
D.append(f"insert into costing.fx_ar select * from jsonb_populate_recordset(null::costing.fx_ar, {J(ar)}::jsonb);")
D.append(f"insert into costing.fx_foundation values (126, {J(pv['foundation'])}::jsonb); insert into costing.fx_dlprev values (126, {J(pv['dlprev'])}::jsonb);")
dem=[dict(x,refresh_run_id=126) for x in r7['dem']]
D.append(f"insert into costing.demand_fixture select * from jsonb_populate_recordset(null::costing.demand_fixture, {J(dem)}::jsonb);")
# live outputs for comparison
for t in ['product_production_overhead_workload_snapshot','product_production_overhead_step_snapshot','sku_production_overhead_allocation_snapshot',
          'product_direct_labour_workload_snapshot','product_direct_labour_step_snapshot','sku_packing_labour_workload_snapshot','sku_direct_labour_allocation_snapshot','batch_true_absorption_variance']:
    D.append(f"create table costing.live_{t} as select * from jsonb_populate_recordset(null::costing.{t}, {J(out[t])}::jsonb);")
D.append(f"create table costing.live_product_qc_allocation_snapshot as select * from jsonb_populate_recordset(null::costing.product_qc_allocation_snapshot, {J(r7['qca'])}::jsonb);")
D.append(f"create table costing.live_sku_qc_allocation_snapshot as select * from jsonb_populate_recordset(null::costing.sku_qc_allocation_snapshot, {J(r7['sqa'])}::jsonb);")
open('fx_data.sql','w').write('\n'.join(D))
print('ok', sum(len(x) for x in D)//1024, 'KB')
